// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Failer {
    fallback() external payable {
        revert("forced failure");
    }
}

contract InvMutTest is Test {
    C c;
    Failer failer;

    function setUp() public {
        c = new C();
        failer = new Failer();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        // bound amounts to reasonable range and ensure actor is not the contract itself
        vm.assume(actor != address(c) && actor != address(failer) && actor != address(this) && actor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, type(uint128).max);

        // give the actor some ether for deposit and cover gas
        vm.deal(actor, depositAmount * 2);

        // actor deposits
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(actor);

        // actor calls withdrawAll via Failer to force a failing transfer
        // The Failer will revert in its fallback, so the call should revert.
        bool ok = false;
        vm.prank(actor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 creditAfter = c.credit(actor);

        // General rule: if the call reverted, state must remain unchanged.
        // If the call succeeded, the transfer must have succeeded and credit is zero.
        // The mutant violates this because it can leave credit=0 even when transfer reverts.
        if (!ok) {
            // reverted -> balances and credit must be unchanged
            assertTrue(balanceAfter == balanceBefore && creditAfter == creditBefore);
        } else {
            // succeeded -> credit must be 0 and balance decreased by returned amount
            assertTrue(creditAfter == 0 && balanceAfter == balanceBefore - creditBefore);
        }
    }
}

