import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 adversarySeed) public {
        vm.assume(depositAmount > 0);
        vm.assume(adversarySeed > 0);

        // Deploy an adversarial callee whose fallback always reverts
        Reverter reverter = new Reverter();
        address adversary = address(reverter);

        // Deposit as the adversary to establish credit
        vm.deal(adversary, depositAmount);
        vm.prank(adversary);
        c.deposit{value: depositAmount}();

        uint256 creditBefore = c.credit(adversary);
        uint256 balanceBefore = address(c).balance;

        // withdrawAll called by the adversary; reference reverts, buggy does not
        bool reverted;
        vm.prank(adversary);
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditAfter = c.credit(adversary);
        uint256 balanceAfter = address(c).balance;

        // General rule: if withdrawAll does not revert, then the caller's credit must be zero AND
        // the contract's balance must have decreased by exactly creditBefore.
        // The reference always reverts (reverted=true) so the antecedent is false, making the implication true.
        // The buggy version does not revert, credit becomes 0 but balance does not decrease -> implication false.
        assertTrue(
            !reverted ? (
                creditAfter == 0 && balanceBefore - balanceAfter == creditBefore
            ) : true
        );
    }
}

