import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Keep amounts in a wide admissible range
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Deploy an adversarial callee that always rejects ETH
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Fund the actor and make a deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record state before withdrawal
        uint256 creditBefore = c.credit(actor);
        uint256 balanceBefore = address(c).balance;

        // Attempt withdrawal; the external call to the Reverter will fail
        vm.prank(actor);
        try c.withdrawAll() {
            // If no revert, the credit must have been subtracted from balance
            // and the ETH actually delivered, which is impossible for the Reverter.
            // The reference always reverts, so this path is only reachable in the buggy version.
            uint256 creditAfter = c.credit(actor);
            uint256 balanceAfter = address(c).balance;
            assertTrue(creditAfter == 0 && balanceAfter == balanceBefore - creditBefore);
        } catch {
            // If it reverted, the state must be unchanged (reference behavior)
            uint256 creditAfter = c.credit(actor);
            uint256 balanceAfter = address(c).balance;
            assertTrue(creditAfter == creditBefore && balanceAfter == balanceBefore);
        }
    }
}

