pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 attackAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(attackAmount > 0 && attackAmount <= depositAmount);

        // Deploy re-entrant attacker that will attempt to double-withdraw
        Attacker attacker = new Attacker();
        address attackerAddr = address(attacker);

        // Fund attacker and make a deposit into C
        vm.deal(attackerAddr, depositAmount);
        vm.prank(attackerAddr);
        c.deposit{value: depositAmount}();

        // Give C enough ETH to cover the potential double withdrawal (balance baseline starts at depositAmount)
        vm.deal(address(c), depositAmount);

        // Prime attacker with the desired attack amount
        attacker.prepare(address(c), attackAmount);

        // Execute attack: attacker calls withdrawAll; its receive() will call withdrawAll again
        vm.prank(attackerAddr);
        attacker.attack();

        // Balance of C should equal the sum of all remaining credits.
        // The attacker's credit must be zero because the full credit was withdrawn exactly once
        // (the re-entrant call should fail because the credit was already set to 0 or the lock prevents re-entry).
        assertTrue(address(c).balance == getTotalCredits());
    }

    function getTotalCredits() internal view returns (uint256 total) {
        // Since credit is private, we cannot read it directly.
        // Instead we reason: after a single deposit, the only credit holder is the attacker, which we can observe.
        // A valid invariant that does not require reading private state is impossible without a helper.
        // Because the specification requires observing only the public surface, we use address(c).balance
        // and the fact that the mutant leaves credit intact while reference clears it.
        // We must deploy a helper that holds the credit on behalf of the attacker.
        // The invariant: after attack, the contract's balance equals zero if the withdrawal succeeded exactly once.
        // Actually, the invariant is that balance drops by exactly the credit amount once.
        // We'll compute the expected balance as depositAmount minus attackAmount (the allowed withdrawal).
        // If re-entrancy succeeds in the mutant, the balance will be further reduced because the credit was not zeroed.
        // So we test: address(c).balance == depositAmount - attackAmount (reference).
        // But we need to assert a general rule.
        // Another approach: after the attack, the attacker's credit in the reference is 0,
        // so a subsequent withdrawAll would fail (no ETH sent). In the mutant, credit > 0 so a subsequent call drains more.
        // We can assert that the contract's balance decreases only once.
        // Since we cannot read credit, we use a helper to measure balance changes.
        // Let's use a different invariant: total ether withdrawn by the attacker equals attackAmount exactly once.
        // We'll use a helper tracker.
        // This is messy. Let's craft a property that uses only public state.
        // Because credit is private, the only public signals are balance and ETH transfers.
        // We deploy a helper that records received ETH and use that.
        // The property: the sum of ETH received by the attacker equals the balance reduction.
        // But the attacker could be re-entrant.
        // We'll simplify: assert that the attack does not cause ETH to be sent more than once.
        // Let attacker receive callback and count how many times receive() is called.
        // If receive is called exactly once, assertTrue; in mutant it's called twice.
        // That's a valid public observation.
        assertTrue(attacker.receiveCount() == 1);
    }
}

contract Attacker {
    C public target;
    uint256 public attackAmount;
    uint256 public receiveCount;

    function prepare(address _target, uint256 _attackAmount) external {
        target = C(_target);
        attackAmount = _attackAmount;
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        receiveCount++;
        if (receiveCount == 1) {
            // Try to withdraw again (re-entrancy)
            target.withdrawAll();
        }
    }
}

