import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to reasonable admissible domain
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, 100 ether);
        vm.assume(depositAmount >= withdrawAmount);

        // Deploy adversarial callee that reverts on receive
        Reverter reverter = new Reverter();

        // Fund an EOA caller who will interact with c
        address caller = makeAddr("caller");
        vm.deal(caller, depositAmount);

        // Caller deposits into c
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // Record credit before withdraw attempt
        uint256 creditBefore = creditGetter(caller);

        // Attempt withdrawAll on behalf of reverter (which will fail)
        // The adversary here is the reverter contract calling withdrawAll.
        // It needs ETH for gas, so we deal some.
        vm.deal(address(reverter), 1 ether);
        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // After a failed withdrawAll, caller's credit must equal credit before the call.
        // The buggy contract zeroes credit before the call, breaking this invariant.
        uint256 creditAfter = creditGetter(caller);
        assertTrue(!ok || creditAfter == 0); // If it succeeded somehow (shouldn't), credit is zero
        assertTrue(ok ? true : creditAfter == creditBefore);
    }

    // Auto-generated getter for public mapping credit
    function creditGetter(address a) internal view returns (uint256) {
        return c.credit(a);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

