        target = C(_target);
        count = (_seed % 3) + 1; // 1..3 reentrant calls
        totalToDrain = _totalToDrain;
    }

    receive() external payable {
        if (depth < count) {
            depth++;
            target.withdrawAll();
        }
    }
}

