pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraDeposit) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1e36);
        vm.assume(extraDeposit <= 1e36);
        address attacker = makeAddr("attacker");
        vm.deal(attacker, depositAmount + extraDeposit);
        // Deposit the attacker's credit
        vm.prank(attacker);
        c.deposit{value: depositAmount}();
        uint256 creditBefore = c.credit(attacker);
        uint256 attackerEthBefore = attacker.balance;
        uint256 contractEthBefore = address(c).balance;
        // Perform withdrawAll; the buggy version allows reentrant drain if attacker is a contract that re-enters
        ReentrantAttacker reentrant = new ReentrantAttacker(c);
        vm.deal(address(reentrant), depositAmount);
        // We transfer the credit to the reentrant contract by depositing from it
        vm.prank(address(reentrant));
        c.deposit{value: depositAmount}();
        uint256 recCreditBefore = c.credit(address(reentrant));
        uint256 recEthBefore = address(reentrant).balance;
        uint256 cEthBefore = address(c).balance;
        reentrant.attack();
        uint256 recEthAfter = address(reentrant).balance;
        uint256 recCreditAfter = c.credit(address(reentrant));
        // The reference contract prevents reentrancy: withdraws exactly once, so ETH gained == original credit and credit becomes 0
        // The mutant allows multiple withdrawals, so ETH gained > original credit
        // Assert: ETH gained by reentrant <= original credit (holds for reference, breaks for mutant)
        assertTrue(recEthAfter - recEthBefore <= recCreditBefore);
    }
}

contract ReentrantAttacker {
    C target;
    bool attacking;
    constructor(C _target) { target = _target; }
    function attack() external {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }
    receive() external payable {
        if (attacking) {
            target.withdrawAll();
        }
    }
}
